// [S4] Three-portal family features — My Doctor: connected doctor with booking,
// a pending-request state, and the verified directory (Family Head only).
import 'package:family_veda/models/doctor_summary.dart';
import 'package:family_veda/models/family_doctor_request.dart';
import 'package:family_veda/providers/family_portal_provider.dart';
import 'package:family_veda/theme/app_theme.dart';
import 'package:family_veda/widgets/family/my_doctor_parts.dart';
import 'package:family_veda/widgets/shared/async_state_views.dart';
import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';

class MyDoctorScreen extends ConsumerWidget {
  const MyDoctorScreen({super.key});

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    return Scaffold(
      backgroundColor: Colors.transparent,
      body: SafeArea(
        child: ref
            .watch(familyDashboardProvider)
            .when(
              loading: () =>
                  const LoadingStateView(label: 'Loading family doctor'),
              error: (_, _) => ErrorRetryView(
                onRetry: () => ref.invalidate(familyDashboardProvider),
              ),
              data: (dashboard) {
                final familyId = dashboard.familyId;
                if (familyId == null) {
                  return const EmptyStateView(
                    title: 'No family found',
                    message: 'Join or create a family first.',
                  );
                }
                return _MyDoctorBody(
                  key: ValueKey(familyId),
                  familyId: familyId,
                  isHead: dashboard.isHead,
                );
              },
            ),
      ),
    );
  }
}

class _MyDoctorBody extends ConsumerStatefulWidget {
  const _MyDoctorBody({
    super.key,
    required this.familyId,
    required this.isHead,
  });

  final String familyId;
  final bool isHead;

  @override
  ConsumerState<_MyDoctorBody> createState() => _MyDoctorBodyState();
}

class _MyDoctorBodyState extends ConsumerState<_MyDoctorBody> {
  bool _directoryOpen = false;
  bool _busy = false;

  void _toast(String message, {bool error = false}) {
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(message),
        backgroundColor: error ? AppColors.danger : AppColors.success,
      ),
    );
  }

  Future<bool> _confirm({
    required String title,
    required String body,
    required String detail,
    required String confirmLabel,
    String cancelLabel = 'Cancel',
  }) async {
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (context) => AlertDialog(
        title: Text(title),
        content: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(body),
            const SizedBox(height: 12),
            Text(detail, style: const TextStyle(fontWeight: FontWeight.w700)),
          ],
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(context, false),
            child: Text(cancelLabel),
          ),
          FilledButton(
            onPressed: () => Navigator.pop(context, true),
            child: Text(confirmLabel),
          ),
        ],
      ),
    );
    return confirmed ?? false;
  }

  Future<void> _request(DoctorSummary doctor, {required bool isChange}) async {
    if (_busy) return;
    final confirmed = await _confirm(
      title: isChange
          ? 'Request a change of family doctor?'
          : 'Send family doctor request?',
      body: isChange
          ? 'Your current doctor stays linked while the new request is pending. No clinical access transfers automatically.'
          : 'This request does not share health records or grant clinical access.',
      detail: doctor.displayName,
      confirmLabel: 'Send request',
    );
    if (!confirmed || !mounted) return;
    setState(() => _busy = true);
    try {
      await ref
          .read(familyPortalApiProvider)
          .requestFamilyDoctor(familyId: widget.familyId, doctorId: doctor.id);
      _toast(
        isChange
            ? 'Change request sent. Your existing doctor stays assigned.'
            : 'Family doctor request sent.',
      );
    } on Object {
      _toast(
        'Could not send the request. There may already be one pending.',
        error: true,
      );
    } finally {
      ref.invalidate(familyDoctorPendingRequestProvider(widget.familyId));
      if (mounted) {
        setState(() {
          _busy = false;
          _directoryOpen = false;
        });
      }
    }
  }

  Future<void> _cancel(
    FamilyDoctorRequest request, {
    required bool isChange,
  }) async {
    if (_busy) return;
    final confirmed = await _confirm(
      title: isChange ? 'Withdraw doctor change?' : 'Cancel this request?',
      body: isChange
          ? 'Your current family doctor remains unchanged.'
          : 'You can browse and request another verified family doctor afterward.',
      detail: 'Pending request: ${request.doctor.displayName}',
      confirmLabel: isChange ? 'Withdraw request' : 'Cancel request',
      cancelLabel: 'Keep request',
    );
    if (!confirmed || !mounted) return;
    setState(() => _busy = true);
    try {
      await ref
          .read(familyPortalApiProvider)
          .cancelDoctorRequest(
            familyId: widget.familyId,
            requestId: request.id,
          );
      _toast(isChange ? 'Change request withdrawn.' : 'Request cancelled.');
    } on Object {
      _toast('Could not cancel the request.', error: true);
    } finally {
      // The doctor may have answered in the meantime; reload what is true now.
      ref.invalidate(familyDoctorPendingRequestProvider(widget.familyId));
      ref.invalidate(familyDoctorProvider(widget.familyId));
      if (mounted) setState(() => _busy = false);
    }
  }

  void _showAccessInfo() {
    showDialog<void>(
      context: context,
      builder: (context) => AlertDialog(
        title: const Text('Privacy and clinical access'),
        content: const Text(
          'Your primary family doctor can manage the care relationship, but medical records require member consent and a valid visit or case grant.\n\nFamily Head is not a blanket clinical-access permission. Adult members control their own medical information and sharing choices.',
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(context),
            child: const Text('Close'),
          ),
        ],
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final palette = MyDoctorPalette.of(context);
    final doctorAsync = ref.watch(familyDoctorProvider(widget.familyId));
    final pendingAsync = ref.watch(
      familyDoctorPendingRequestProvider(widget.familyId),
    );
    if (doctorAsync.hasError || pendingAsync.hasError) {
      return ErrorRetryView(
        onRetry: () {
          ref.invalidate(familyDoctorProvider(widget.familyId));
          ref.invalidate(familyDoctorPendingRequestProvider(widget.familyId));
        },
      );
    }
    if (!doctorAsync.hasValue || !pendingAsync.hasValue) {
      return const LoadingStateView(label: 'Loading family doctor');
    }
    final doctor = doctorAsync.value;
    final pending = pendingAsync.value;

    return ListView(
      padding: const EdgeInsets.fromLTRB(16, 12, 16, 28),
      children: [
        const MyDoctorEyebrow('Your long-term care relationship'),
        const SizedBox(height: 6),
        Text(
          'My Doctor',
          style: TextStyle(
            fontSize: 28,
            fontWeight: FontWeight.w800,
            letterSpacing: -0.8,
            color: palette.heading,
          ),
        ),
        const SizedBox(height: 4),
        Text(
          'One trusted family doctor, with appointments and care in one place.',
          style: TextStyle(fontSize: 13.5, color: palette.muted),
        ),
        const SizedBox(height: 10),
        Align(
          alignment: Alignment.centerLeft,
          child: OutlinedButton.icon(
            onPressed: () => context.go('/appointments'),
            icon: const Icon(Icons.calendar_month_outlined, size: 18),
            label: const Text('My appointments'),
          ),
        ),
        const SizedBox(height: 14),
        if (doctor != null)
          ..._assigned(palette, doctor, pending)
        else if (pending != null)
          _pendingState(palette, pending)
        else
          _noDoctorState(palette),
      ],
    );
  }

  List<Widget> _assigned(
    MyDoctorPalette palette,
    DoctorSummary doctor,
    FamilyDoctorRequest? pending,
  ) {
    final subtitle = [
      doctor.specialty,
      doctor.clinic,
    ].whereType<String>().where((value) => value.isNotEmpty).join(' · ');
    return [
      MyDoctorPanel(
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Row(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                const Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      MyDoctorEyebrow('Primary family doctor'),
                      SizedBox(height: 4),
                      Text(
                        'Your doctor',
                        style: TextStyle(
                          fontSize: 17,
                          fontWeight: FontWeight.w700,
                        ),
                      ),
                    ],
                  ),
                ),
                MyDoctorTag(
                  'Connected',
                  color: palette.success,
                  icon: Icons.circle,
                ),
              ],
            ),
            const SizedBox(height: 16),
            Row(
              children: [
                MyDoctorAvatar(doctor.displayName, size: 62),
                const SizedBox(width: 12),
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                        doctor.displayName,
                        style: const TextStyle(
                          fontSize: 19,
                          fontWeight: FontWeight.w700,
                          letterSpacing: -0.4,
                        ),
                      ),
                      if (subtitle.isNotEmpty)
                        Text(
                          subtitle,
                          style: TextStyle(fontSize: 12, color: palette.muted),
                        ),
                      const SizedBox(height: 6),
                      MyDoctorTag(
                        'Verified practitioner',
                        color: palette.primary,
                        icon: Icons.verified_user_outlined,
                      ),
                    ],
                  ),
                ),
              ],
            ),
            Divider(height: 32, color: palette.line),
            _fact(palette, Icons.work_outline, 'Specialty', doctor.specialty),
            _fact(
              palette,
              Icons.location_on_outlined,
              'Clinic location',
              doctorPlace(doctor),
            ),
            _fact(palette, Icons.language, 'Languages', doctor.languages),
            _fact(
              palette,
              Icons.local_hospital_outlined,
              'Clinic',
              doctor.clinic,
            ),
            const SizedBox(height: 6),
            const MyDoctorNote(
              title: 'Personal information stays protected',
              body:
                  'A long-term doctor relationship does not automatically grant access to your medical records. Sharing requires consent and a valid clinical access grant.',
            ),
            const SizedBox(height: 12),
            SizedBox(
              width: double.infinity,
              child: OutlinedButton.icon(
                onPressed: () => showDoctorProfile(context, doctor),
                iconAlignment: IconAlignment.end,
                icon: const Icon(Icons.chevron_right, size: 18),
                label: const Text('View profile'),
              ),
            ),
          ],
        ),
      ),
      MyDoctorBookingCard(key: ValueKey(doctor.id), familyId: widget.familyId),
      MyDoctorPanel(
        child: Row(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Icon(Icons.lock_outline, color: palette.primary),
            const SizedBox(width: 12),
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  const Text(
                    'Your health data, your choice',
                    style: TextStyle(fontSize: 14, fontWeight: FontWeight.w700),
                  ),
                  const SizedBox(height: 4),
                  Text(
                    'You control who can access your records. Adult members manage their own privacy; Family Head permissions do not override their choices.',
                    style: TextStyle(fontSize: 12, color: palette.muted),
                  ),
                  TextButton(
                    style: TextButton.styleFrom(padding: EdgeInsets.zero),
                    onPressed: _showAccessInfo,
                    child: const Text('Understand access permissions'),
                  ),
                ],
              ),
            ),
          ],
        ),
      ),
      if (pending != null)
        Padding(
          padding: const EdgeInsets.only(bottom: 14),
          child: MyDoctorNote(
            icon: Icons.schedule,
            color: palette.warning,
            title: 'Change request pending: ${pending.doctor.displayName}',
            body:
                'Your current doctor remains connected until the new doctor accepts the request.',
            action: widget.isHead
                ? OutlinedButton(
                    onPressed: _busy
                        ? null
                        : () => _cancel(pending, isChange: true),
                    child: const Text('Withdraw request'),
                  )
                : null,
          ),
        ),
      if (widget.isHead)
        MyDoctorPanel(
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              const Text(
                'Find another family doctor',
                style: TextStyle(fontSize: 15, fontWeight: FontWeight.w700),
              ),
              const SizedBox(height: 3),
              Text(
                'Optional — this directory stays collapsed when you already have a doctor.',
                style: TextStyle(fontSize: 12, color: palette.muted),
              ),
              const SizedBox(height: 10),
              OutlinedButton.icon(
                onPressed: pending != null
                    ? null
                    : () => setState(() => _directoryOpen = !_directoryOpen),
                iconAlignment: IconAlignment.end,
                icon: Icon(
                  _directoryOpen ? Icons.expand_less : Icons.expand_more,
                  size: 18,
                ),
                label: Text(
                  _directoryOpen ? 'Hide directory' : 'Explore directory',
                ),
              ),
              if (_directoryOpen && pending == null) ...[
                const SizedBox(height: 12),
                MyDoctorNote(
                  icon: Icons.info_outline,
                  title: 'Your current doctor remains assigned',
                  body:
                      'Sending a change request will not remove ${doctor.displayName}. The new doctor must accept the request before the relationship changes.',
                ),
                const SizedBox(height: 14),
                MyDoctorDirectory(
                  requestLabel: 'Request change',
                  currentDoctorId: doctor.id,
                  onRequest: (target) => _request(target, isChange: true),
                ),
              ],
            ],
          ),
        ),
    ];
  }

  Widget _fact(
    MyDoctorPalette palette,
    IconData icon,
    String label,
    String? value,
  ) => Padding(
    padding: const EdgeInsets.only(bottom: 12),
    child: Row(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Icon(icon, size: 18, color: palette.primary),
        const SizedBox(width: 10),
        Expanded(
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text(label, style: TextStyle(fontSize: 11, color: palette.muted)),
              Text(
                value?.trim().isNotEmpty == true ? value! : 'Not provided',
                style: const TextStyle(
                  fontSize: 13,
                  fontWeight: FontWeight.w600,
                ),
              ),
            ],
          ),
        ),
      ],
    ),
  );

  Widget _hero(
    MyDoctorPalette palette, {
    required IconData icon,
    required Color color,
    required String tag,
    required String title,
    required String body,
  }) => Padding(
    padding: const EdgeInsets.fromLTRB(4, 10, 4, 18),
    child: Column(
      children: [
        Container(
          width: 64,
          height: 64,
          decoration: BoxDecoration(
            color: color.withValues(alpha: 0.14),
            borderRadius: BorderRadius.circular(19),
            border: Border.all(color: color.withValues(alpha: 0.5)),
          ),
          child: Icon(icon, size: 28, color: color),
        ),
        const SizedBox(height: 12),
        MyDoctorTag(tag, color: color),
        const SizedBox(height: 12),
        Text(
          title,
          textAlign: TextAlign.center,
          style: TextStyle(
            fontSize: 22,
            fontWeight: FontWeight.w700,
            letterSpacing: -0.5,
            color: palette.heading,
          ),
        ),
        const SizedBox(height: 6),
        Text(
          body,
          textAlign: TextAlign.center,
          style: TextStyle(fontSize: 13, height: 1.45, color: palette.muted),
        ),
      ],
    ),
  );

  Widget _pendingState(MyDoctorPalette palette, FamilyDoctorRequest pending) {
    final doctor = pending.doctor;
    final meta = [
      doctor.specialty ?? '',
      doctorPlace(doctor),
    ].where((value) => value.isNotEmpty).join(' · ');
    return MyDoctorPanel(
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          _hero(
            palette,
            icon: Icons.schedule,
            color: palette.warning,
            tag: 'Awaiting doctor response',
            title: 'Your request is on its way.',
            body:
                'Your family doctor request has been submitted. The practitioner can accept or decline it. No health information is shared before acceptance.',
          ),
          Container(
            padding: const EdgeInsets.all(14),
            decoration: BoxDecoration(
              color: palette.warning.withValues(alpha: 0.08),
              borderRadius: BorderRadius.circular(14),
              border: Border.all(
                color: palette.warning.withValues(alpha: 0.45),
              ),
            ),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Row(
                  children: [
                    MyDoctorAvatar(doctor.displayName),
                    const SizedBox(width: 11),
                    Expanded(
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Text(
                            doctor.displayName,
                            style: const TextStyle(
                              fontSize: 14.5,
                              fontWeight: FontWeight.w700,
                            ),
                          ),
                          if (meta.isNotEmpty)
                            Text(
                              meta,
                              style: TextStyle(
                                fontSize: 12,
                                color: palette.muted,
                              ),
                            ),
                          const SizedBox(height: 6),
                          MyDoctorTag(
                            'Request pending',
                            color: palette.warning,
                            icon: Icons.circle,
                          ),
                        ],
                      ),
                    ),
                  ],
                ),
                if (widget.isHead) ...[
                  const SizedBox(height: 12),
                  SizedBox(
                    width: double.infinity,
                    child: OutlinedButton(
                      onPressed: _busy
                          ? null
                          : () => _cancel(pending, isChange: false),
                      child: const Text('Cancel request'),
                    ),
                  ),
                ],
              ],
            ),
          ),
          const SizedBox(height: 14),
          const MyDoctorNote(
            title: 'Private until connection is accepted',
            body:
                'Doctors see only the information needed to respond to a relationship request. Consent and member-specific grants are handled separately.',
          ),
        ],
      ),
    );
  }

  Widget _noDoctorState(MyDoctorPalette palette) => MyDoctorPanel(
    child: Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        _hero(
          palette,
          icon: Icons.monitor_heart_outlined,
          color: palette.primary,
          tag: 'No doctor connected yet',
          title: 'Find a doctor your family can rely on.',
          body: widget.isHead
              ? 'Browse verified practitioners, compare practice details, and send a long-term family doctor request. Your family selects the doctor.'
              : 'Your family head can choose and request a doctor for the family. The doctor will appear here after they accept.',
        ),
        if (widget.isHead) ...[
          const Text(
            'Explore verified family doctors',
            style: TextStyle(fontSize: 15, fontWeight: FontWeight.w700),
          ),
          const SizedBox(height: 3),
          Text(
            'Search by name, specialty, district or language.',
            style: TextStyle(fontSize: 12, color: palette.muted),
          ),
          const SizedBox(height: 14),
          MyDoctorDirectory(
            requestLabel: 'Request doctor',
            onRequest: (target) => _request(target, isChange: false),
          ),
        ],
      ],
    ),
  );
}
